static COLOURS: [[[Color32; 3]; 8]; 25] = parse();
static CLASSIC_COLOURS: [[[[Color32; 3]; 10]; 2]; 25] = parse_classic();
static NAMES: [&str; 25] = names();
static BASES: [[u8; 3]; 25] = bases();

const fn names() -> [&'static str; 25] {
    let mut out = [""; 25];
    let mut row = 0;
    while row < ROWS.len() {
        out[row] = ROWS[row].name;
        row += 1;
    }
    out
}

const fn bases() -> [[u8; 3]; 25] {
    let mut out = [[0; 3]; 25];
    let mut row = 0;
    while row < ROWS.len() {
        out[row] = ROWS[row].base;
        row += 1;
    }
    out
}

