const fn parse_classic() -> [[[[Color32; 3]; 10]; 2]; 25] {
    let mut out = [[[[Color32::TRANSPARENT; 3]; 10]; 2]; 25];
    let mut row = 0;
    while row < CLASSIC.len() {
        let mut theme = 0;
        while theme < 2 {
            let mut state = 0;
            while state < 10 {
                let mut part = 0;
                while part < 3 {
                    out[row][theme][state][part] = css_color(CLASSIC[row][theme][state][part]);
                    part += 1;
                }
                state += 1;
            }
            theme += 1;
        }
        row += 1;
    }
    out
}

/// Each row's colours, three to a palette.
const fn parse() -> [[[Color32; 3]; 8]; 25] {
    let mut out = [[[Color32::TRANSPARENT; 3]; 8]; 25];
    let mut row = 0;
    while row < ROWS.len() {
        let values = &ROWS[row].classic;
        let mut at = 0;
        while at < values.len() {
            out[row][at / 3][at % 3] = css_color(values[at]);
            at += 1;
        }
        row += 1;
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn names_resolve() {
        assert_eq!(
            CalendarColor::from_name("purple"),
            CalendarColor::from_name("magenta")
        );
        assert_eq!(CalendarColor::BLUE.name(), "blue");
        assert_eq!(CalendarColor::picker().count(), 25);
        let blue = CalendarColor::BLUE.block(Theme::Snow, BlockPalette::default());
        assert_eq!(
            (blue.text, blue.fill, blue.border),
            (
                Color32::WHITE,
                Color32::from_rgb(115, 182, 219),
                Color32::WHITE
            )
        );
        assert_eq!(
            CalendarColor::BLUE.swatch(Theme::Carbon),
            CalendarColor::BLUE.base()
        );
    }

    #[test]
    fn classic_blocks_keep_the_tokens_but_where_classic_differs() {
        // Snow's plain states are the tokens'; a preview's border is its text colour.
        for color in CalendarColor::all() {
            let tokens = COLOURS[color.0];
            for (index, classic) in CLASSIC_COLOURS[color.0][0].iter().take(8).enumerate() {
                let expected = if index == 2 || index == 3 {
                    [tokens[index][0], tokens[index][1], tokens[index][0]]
                } else {
                    tokens[index]
                };
                assert_eq!(*classic, expected, "{} snow state {index}", color.name());
            }
        }
        // Carbon's filled blue is darker than the token (`rgb(99.8, 153.8, 184.2)`).
        assert_eq!(
            CalendarColor::BLUE
                .block(Theme::Carbon, BlockPalette::default())
                .fill,
            Color32::from_rgb(100, 154, 184)
        );
    }
}
